import { test } from "@fast-check/vitest";
import fc from "fast-check";
import { describe, expect, it } from "vitest";
import { renderLocales, renderRegistry } from "../registry.js";

const HEADER =
  "// generated by GatoJS — do not edit. Run: npm run wa -- generate";
const CONFIG_IMPORT = 'import gatoConfig from "@/gato.config";';
const EMPTY_CONFIG_IMPORT =
  'import { emptyGatoConfig as gatoConfig } from "@/shared/lib/modules/gato-config";';
const BOTH_HELPERS_IMPORT =
  'import { applyGatoConfig, enabledEntries } from "@/shared/lib/modules/gato-config";';
const BOTH = ["pl", "en"] as ("pl" | "en")[];

const base = {
  hasModuleTs: false,
  hasEnv: false,
  hasAuth: false,
  hasAuthClient: false,
  hasAuditSink: false,
  locales: [],
};

describe("renderRegistry", () => {
  it("emituje importy i tablice dla modułu z wszystkimi plikami", () => {
    const { server, client } = renderRegistry(
      [
        {
          name: "demo",
          hasModuleTs: true,
          hasEnv: true,
          hasAuth: true,
          hasAuthClient: true,
          hasAuditSink: false,
          locales: ["pl", "en"],
        },
      ],
      BOTH,
    );
    expect(
      server.startsWith(
        "// generated by GatoJS — do not edit. Run: npm run wa -- generate\n",
      ),
    ).toBe(true);
    expect(server).toContain(
      'import demoModule from "@/features/demo/module";',
    );
    expect(server).toContain(
      'import { envSchema as demoEnvSchema } from "@/features/demo/env";',
    );
    expect(server).toContain(
      'import { authPlugin as demoAuthPlugin } from "@/features/demo/auth";',
    );
    expect(server).toContain(
      "export const modules = applyGatoConfig([demoModule], gatoConfig);",
    );
    expect(server).toContain(
      '{ module: "demo", value: { key: "demo", load: () => import("@/features/demo/i18n/pl.json").then((m) => m.default) } }',
    );
    expect(server).toContain('import("@/features/demo/i18n/en.json")');
    expect(
      client.startsWith(
        "// generated by GatoJS — do not edit. Run: npm run wa -- generate\n",
      ),
    ).toBe(true);
    expect(client).toContain(
      'import { authClientPlugin as demoAuthClientPlugin } from "@/features/demo/auth-client";',
    );
    expect(client).toContain(
      'export const authClientPlugins = enabledEntries([{ module: "demo", value: demoAuthClientPlugin }], gatoConfig);',
    );
    expect(client).toContain(
      "export const clientModules = applyGatoConfig([demoModule], gatoConfig);",
    );
  });

  it("moduły bez plików dają puste tablice i puste locale", () => {
    const { server, client } = renderRegistry([{ name: "x", ...base }], BOTH);
    expect(server).toContain("export const modules: never[] = [];");
    expect(server).toContain("pl: [],");
    expect(client).toContain("export const clientModules: never[] = [];");
    expect(server).not.toContain("gatoConfig");
    expect(client).not.toContain("gatoConfig");
  });

  it("klient eksportuje pełne obiekty modułów, nie projekcję pól", () => {
    const { client } = renderRegistry(
      [
        { name: "a", ...base, hasModuleTs: true },
        { name: "b", ...base, hasModuleTs: true },
      ],
      BOTH,
    );
    expect(client).toContain(
      "export const clientModules = applyGatoConfig([aModule, bModule], gatoConfig);",
    );
    expect(client).not.toContain("routePrefixes:");
  });

  it("nazwy z myślnikiem dają poprawne identyfikatory", () => {
    const { server } = renderRegistry(
      [{ name: "my-feature", ...base, hasModuleTs: true }],
      BOTH,
    );
    expect(server).toContain(
      'import myFeatureModule from "@/features/my-feature/module";',
    );
  });

  it("kolejność wejściowa jest zachowana", () => {
    const { server } = renderRegistry(
      [
        { name: "b", ...base, hasModuleTs: true },
        { name: "a", ...base, hasModuleTs: true },
      ],
      BOTH,
    );
    expect(server).toContain(
      "export const modules = applyGatoConfig([bModule, aModule], gatoConfig);",
    );
  });
  const demo = {
    name: "demo",
    hasModuleTs: true,
    hasEnv: true,
    hasAuth: true,
    hasAuthClient: true,
    hasAuditSink: false,
    locales: ["pl", "en"],
  };

  it("serwer ma pełny kontrakt pliku dla modułu ze wszystkim", () => {
    expect(renderRegistry([demo], BOTH).server).toEqual(
      [
        "// generated by GatoJS — do not edit. Run: npm run wa -- generate",
        'import { emptyGatoConfig as gatoConfig } from "@/shared/lib/modules/gato-config";',
        'import type { Locale } from "@/i18n/config";',
        'import { createEnv } from "@gatojs/env";',
        'import { applyGatoConfig, enabledEntries } from "@/shared/lib/modules/gato-config";',
        'import demoModule from "@/features/demo/module";',
        'import { envSchema as demoEnvSchema } from "@/features/demo/env";',
        'import { authPlugin as demoAuthPlugin } from "@/features/demo/auth";',
        "",
        "export const modules = applyGatoConfig([demoModule], gatoConfig);",
        'export const moduleEnvSchemas = enabledEntries([{ module: "demo", value: demoEnvSchema }], gatoConfig);',
        'export const authPlugins = enabledEntries([{ module: "demo", value: demoAuthPlugin }], gatoConfig);',
        "export const auditSinks: never[] = [];",
        "export const env = createEnv(moduleEnvSchemas);",
        "",
        "export type MessageLoader = { key: string; load: () => Promise<Record<string, unknown>> };",
        "",
        "export const moduleMessages: Record<Locale, MessageLoader[]> = {",
        "  pl: enabledEntries<MessageLoader>([",
        '    { module: "demo", value: { key: "demo", load: () => import("@/features/demo/i18n/pl.json").then((m) => m.default) } },',
        "  ], gatoConfig),",
        "  en: enabledEntries<MessageLoader>([",
        '    { module: "demo", value: { key: "demo", load: () => import("@/features/demo/i18n/en.json").then((m) => m.default) } },',
        "  ], gatoConfig),",
        "};",
        "",
      ].join("\n"),
    );
  });

  it("klient ma pełny kontrakt pliku dla modułu ze wszystkim", () => {
    expect(renderRegistry([demo], BOTH).client).toEqual(
      [
        "// generated by GatoJS — do not edit. Run: npm run wa -- generate",
        'import { emptyGatoConfig as gatoConfig } from "@/shared/lib/modules/gato-config";',
        'import { applyGatoConfig, enabledEntries } from "@/shared/lib/modules/gato-config";',
        'import { authClientPlugin as demoAuthClientPlugin } from "@/features/demo/auth-client";',
        'import demoModule from "@/features/demo/module";',
        "",
        'export const authClientPlugins = enabledEntries([{ module: "demo", value: demoAuthClientPlugin }], gatoConfig);',
        "export const clientModules = applyGatoConfig([demoModule], gatoConfig);",
        "",
      ].join("\n"),
    );
  });

  it("moduł bez env, auth i auth-client nie trafia do tych importów i tablic", () => {
    const { server, client } = renderRegistry(
      [
        demo,
        {
          name: "b",
          hasModuleTs: true,
          hasEnv: false,
          hasAuth: false,
          hasAuthClient: false,
          hasAuditSink: false,
          locales: [],
        },
      ],
      BOTH,
    );
    expect(server).not.toContain("@/features/b/env");
    expect(server).not.toContain("@/features/b/auth");
    expect(server).toContain(
      'export const moduleEnvSchemas = enabledEntries([{ module: "demo", value: demoEnvSchema }], gatoConfig);',
    );
    expect(server).toContain(
      'export const authPlugins = enabledEntries([{ module: "demo", value: demoAuthPlugin }], gatoConfig);',
    );
    expect(server).toContain(
      "export const modules = applyGatoConfig([demoModule, bModule], gatoConfig);",
    );
    expect(client).not.toContain("@/features/b/auth-client");
    expect(client).toContain(
      'export const authClientPlugins = enabledEntries([{ module: "demo", value: demoAuthClientPlugin }], gatoConfig);',
    );
    expect(client).toContain(
      "export const clientModules = applyGatoConfig([demoModule, bModule], gatoConfig);",
    );
  });

  it("kolejne separatory w nazwie daje jeden człon camelCase", () => {
    const { server } = renderRegistry(
      [{ name: "my--mod", ...base, hasModuleTs: true }],
      BOTH,
    );
    expect(server).toContain(
      'import myModModule from "@/features/my--mod/module";',
    );
    expect(server).toContain(
      "export const modules = applyGatoConfig([myModModule], gatoConfig);",
    );
  });

  it("locales [pl] pomija klucz en i loadery en w pełnym pliku serwera", () => {
    expect(renderRegistry([demo], ["pl"]).server).toEqual(
      [
        HEADER,
        EMPTY_CONFIG_IMPORT,
        'import type { Locale } from "@/i18n/config";',
        'import { createEnv } from "@gatojs/env";',
        BOTH_HELPERS_IMPORT,
        'import demoModule from "@/features/demo/module";',
        'import { envSchema as demoEnvSchema } from "@/features/demo/env";',
        'import { authPlugin as demoAuthPlugin } from "@/features/demo/auth";',
        "",
        "export const modules = applyGatoConfig([demoModule], gatoConfig);",
        'export const moduleEnvSchemas = enabledEntries([{ module: "demo", value: demoEnvSchema }], gatoConfig);',
        'export const authPlugins = enabledEntries([{ module: "demo", value: demoAuthPlugin }], gatoConfig);',
        "export const auditSinks: never[] = [];",
        "export const env = createEnv(moduleEnvSchemas);",
        "",
        "export type MessageLoader = { key: string; load: () => Promise<Record<string, unknown>> };",
        "",
        "export const moduleMessages: Record<Locale, MessageLoader[]> = {",
        "  pl: enabledEntries<MessageLoader>([",
        '    { module: "demo", value: { key: "demo", load: () => import("@/features/demo/i18n/pl.json").then((m) => m.default) } },',
        "  ], gatoConfig),",
        "};",
        "",
      ].join("\n"),
    );
  });

  it("locales [pl] nie zmienia pliku klienta", () => {
    expect(renderRegistry([demo], ["pl"]).client).toEqual(
      renderRegistry([demo], BOTH).client,
    );
  });

  it("locales [pl] z modułem tylko z en daje pustą listę pl i brak en", () => {
    const { server } = renderRegistry(
      [{ name: "x", ...base, locales: ["en"] }],
      ["pl"],
    );
    expect(server).toContain("  pl: [],");
    expect(server).not.toContain("en:");
    expect(server).not.toContain("en.json");
  });

  it("locales [pl, en] emituje oba klucze, gdy żaden moduł nie ma tłumaczeń", () => {
    const { server } = renderRegistry([{ name: "x", ...base }], BOTH);
    expect(server).toContain("  pl: [],\n  en: [],\n};");
  });

  it("locales [en, pl] zachowuje kolejność z wejścia", () => {
    const { server } = renderRegistry([{ name: "x", ...base }], ["en", "pl"]);
    expect(server).toContain("  en: [],\n  pl: [],\n};");
  });

  it("renderLocales dla [pl] daje nagłówek i stałą as const", () => {
    expect(renderLocales(["pl"])).toBe(
      `${HEADER}\nexport const locales = ["pl"] as const;\n`,
    );
  });

  it("renderLocales dla [pl, en] daje nagłówek i stałą as const", () => {
    expect(renderLocales(["pl", "en"])).toBe(
      `${HEADER}\nexport const locales = ["pl", "en"] as const;\n`,
    );
  });

  it("moduł z audit-sink.ts daje import i tablicę auditSinks", () => {
    const { server } = renderRegistry(
      [{ name: "audit-logs", ...base, hasAuditSink: true }],
      BOTH,
    );
    expect(server.split("\n")).toContain(
      'import { auditSink as auditLogsAuditSink } from "@/features/audit-logs/audit-sink";',
    );
    expect(server.split("\n")).toContain(
      'export const auditSinks = enabledEntries([{ module: "audit-logs", value: auditLogsAuditSink }], gatoConfig);',
    );
  });

  it("brak modułów z audit-sink.ts daje auditSinks jako never[]", () => {
    const { server } = renderRegistry([{ name: "x", ...base }], BOTH);
    expect(server.split("\n")).toContain(
      "export const auditSinks: never[] = [];",
    );
    expect(server).not.toContain("audit-sink");
  });

  it("moduł bez audit-sink.ts nie trafia do importów i tablicy auditSinks", () => {
    const { server } = renderRegistry(
      [
        { name: "audit-logs", ...base, hasAuditSink: true },
        { name: "b", ...base, hasModuleTs: true },
      ],
      BOTH,
    );
    expect(server).not.toContain("@/features/b/audit-sink");
    expect(server).not.toContain("bAuditSink");
    expect(server.split("\n")).toContain(
      'export const auditSinks = enabledEntries([{ module: "audit-logs", value: auditLogsAuditSink }], gatoConfig);',
    );
  });

  it("dwa moduły z audit-sink.ts zachowują kolejność wejściową", () => {
    const { server } = renderRegistry(
      [
        { name: "alpha", ...base, hasAuditSink: true },
        { name: "beta", ...base, hasAuditSink: true },
      ],
      BOTH,
    );
    expect(server.split("\n")).toContain(
      'export const auditSinks = enabledEntries([{ module: "alpha", value: alphaAuditSink }, { module: "beta", value: betaAuditSink }], gatoConfig);',
    );
    expect(server).toContain(
      'import { auditSink as alphaAuditSink } from "@/features/alpha/audit-sink";\nimport { auditSink as betaAuditSink } from "@/features/beta/audit-sink";',
    );
  });

  it("auditSinks nie trafia do pliku klienta", () => {
    const { client } = renderRegistry(
      [{ name: "audit-logs", ...base, hasModuleTs: true, hasAuditSink: true }],
      BOTH,
    );
    expect(client).not.toContain("audit-sink");
    expect(client).not.toContain("auditSinks");
    expect(client).not.toContain("AuditSink");
    expect(client).toBe(
      [
        HEADER,
        EMPTY_CONFIG_IMPORT,
        'import { applyGatoConfig } from "@/shared/lib/modules/gato-config";',
        'import auditLogsModule from "@/features/audit-logs/module";',
        "",
        "export const authClientPlugins: never[] = [];",
        "export const clientModules = applyGatoConfig([auditLogsModule], gatoConfig);",
        "",
      ].join("\n"),
    );
  });

  test.prop([fc.stringMatching(/^[a-z][a-z0-9]*([-_.][a-z0-9]+)*$/)])(
    "identyfikator importu modułu zawiera tylko znaki alfanumeryczne",
    (name) => {
      const { server } = renderRegistry(
        [{ name, ...base, hasModuleTs: true }],
        BOTH,
      );
      const importLine =
        server
          .split("\n")
          .find((line) => /^import \w+ from "@\/features\//.test(line)) ?? "";
      expect(importLine).toMatch(/^import [A-Za-z0-9]+Module from "/);
    },
  );
});

describe("renderRegistry: env binding from @gatojs/env", () => {
  it("with no modules the server file still imports createEnv and binds env to the empty schema list", () => {
    expect(renderRegistry([], ["pl"]).server).toBe(
      [
        HEADER,
        'import type { Locale } from "@/i18n/config";',
        'import { createEnv } from "@gatojs/env";',
        "",
        "export const modules: never[] = [];",
        "export const moduleEnvSchemas: never[] = [];",
        "export const authPlugins: never[] = [];",
        "export const auditSinks: never[] = [];",
        "export const env = createEnv(moduleEnvSchemas);",
        "",
        "export type MessageLoader = { key: string; load: () => Promise<Record<string, unknown>> };",
        "",
        "export const moduleMessages: Record<Locale, MessageLoader[]> = {",
        "  pl: [],",
        "};",
        "",
      ].join("\n"),
    );
  });

  it("with an env module the createEnv import follows the Locale import and env follows auditSinks", () => {
    const lines = renderRegistry(
      [
        {
          name: "demo",
          ...base,
          hasModuleTs: true,
          hasEnv: true,
          hasAuditSink: true,
        },
      ],
      BOTH,
    ).server.split("\n");

    expect(lines.slice(1, 4)).toEqual([
      EMPTY_CONFIG_IMPORT,
      'import type { Locale } from "@/i18n/config";',
      'import { createEnv } from "@gatojs/env";',
    ]);
    const modulesLine = lines.indexOf(
      "export const modules = applyGatoConfig([demoModule], gatoConfig);",
    );

    expect(lines.slice(modulesLine, modulesLine + 6)).toEqual([
      "export const modules = applyGatoConfig([demoModule], gatoConfig);",
      'export const moduleEnvSchemas = enabledEntries([{ module: "demo", value: demoEnvSchema }], gatoConfig);',
      "export const authPlugins: never[] = [];",
      'export const auditSinks = enabledEntries([{ module: "demo", value: demoAuditSink }], gatoConfig);',
      "export const env = createEnv(moduleEnvSchemas);",
      "",
    ]);
  });

  it("the server file declares createEnv and env exactly once", () => {
    const { server } = renderRegistry(
      [
        { name: "a", ...base, hasEnv: true },
        { name: "b", ...base, hasEnv: true },
      ],
      BOTH,
    );

    expect(
      server.split("\n").filter((line) => line.includes("createEnv")),
    ).toEqual([
      'import { createEnv } from "@gatojs/env";',
      "export const env = createEnv(moduleEnvSchemas);",
    ]);
  });

  it("the client file does not bind env nor import @gatojs/env", () => {
    const { client } = renderRegistry(
      [{ name: "demo", ...base, hasModuleTs: true, hasEnv: true }],
      BOTH,
    );

    expect(client).not.toContain("@gatojs/env");
    expect(client).not.toContain("createEnv");
  });
});

describe("renderRegistry: gato.config", () => {
  const full = {
    name: "demo",
    hasModuleTs: true,
    hasEnv: true,
    hasAuth: true,
    hasAuthClient: true,
    hasAuditSink: true,
    locales: ["pl", "en"],
  };

  it("with hasGatoConfig the server file imports the project config and wraps every list", () => {
    expect(
      renderRegistry([full], BOTH, { hasGatoConfig: true }).server,
    ).toEqual(
      [
        "// generated by GatoJS — do not edit. Run: npm run wa -- generate",
        'import gatoConfig from "@/gato.config";',
        'import type { Locale } from "@/i18n/config";',
        'import { createEnv } from "@gatojs/env";',
        'import { applyGatoConfig, enabledEntries } from "@/shared/lib/modules/gato-config";',
        'import demoModule from "@/features/demo/module";',
        'import { envSchema as demoEnvSchema } from "@/features/demo/env";',
        'import { authPlugin as demoAuthPlugin } from "@/features/demo/auth";',
        'import { auditSink as demoAuditSink } from "@/features/demo/audit-sink";',
        "",
        "export const modules = applyGatoConfig([demoModule], gatoConfig);",
        'export const moduleEnvSchemas = enabledEntries([{ module: "demo", value: demoEnvSchema }], gatoConfig);',
        'export const authPlugins = enabledEntries([{ module: "demo", value: demoAuthPlugin }], gatoConfig);',
        'export const auditSinks = enabledEntries([{ module: "demo", value: demoAuditSink }], gatoConfig);',
        "export const env = createEnv(moduleEnvSchemas);",
        "",
        "export type MessageLoader = { key: string; load: () => Promise<Record<string, unknown>> };",
        "",
        "export const moduleMessages: Record<Locale, MessageLoader[]> = {",
        "  pl: enabledEntries<MessageLoader>([",
        '    { module: "demo", value: { key: "demo", load: () => import("@/features/demo/i18n/pl.json").then((m) => m.default) } },',
        "  ], gatoConfig),",
        "  en: enabledEntries<MessageLoader>([",
        '    { module: "demo", value: { key: "demo", load: () => import("@/features/demo/i18n/en.json").then((m) => m.default) } },',
        "  ], gatoConfig),",
        "};",
        "",
      ].join("\n"),
    );
  });

  it("without hasGatoConfig the server file aliases emptyGatoConfig and is otherwise identical", () => {
    expect(
      renderRegistry([full], BOTH, { hasGatoConfig: false }).server,
    ).toEqual(
      [
        "// generated by GatoJS — do not edit. Run: npm run wa -- generate",
        'import { emptyGatoConfig as gatoConfig } from "@/shared/lib/modules/gato-config";',
        'import type { Locale } from "@/i18n/config";',
        'import { createEnv } from "@gatojs/env";',
        'import { applyGatoConfig, enabledEntries } from "@/shared/lib/modules/gato-config";',
        'import demoModule from "@/features/demo/module";',
        'import { envSchema as demoEnvSchema } from "@/features/demo/env";',
        'import { authPlugin as demoAuthPlugin } from "@/features/demo/auth";',
        'import { auditSink as demoAuditSink } from "@/features/demo/audit-sink";',
        "",
        "export const modules = applyGatoConfig([demoModule], gatoConfig);",
        'export const moduleEnvSchemas = enabledEntries([{ module: "demo", value: demoEnvSchema }], gatoConfig);',
        'export const authPlugins = enabledEntries([{ module: "demo", value: demoAuthPlugin }], gatoConfig);',
        'export const auditSinks = enabledEntries([{ module: "demo", value: demoAuditSink }], gatoConfig);',
        "export const env = createEnv(moduleEnvSchemas);",
        "",
        "export type MessageLoader = { key: string; load: () => Promise<Record<string, unknown>> };",
        "",
        "export const moduleMessages: Record<Locale, MessageLoader[]> = {",
        "  pl: enabledEntries<MessageLoader>([",
        '    { module: "demo", value: { key: "demo", load: () => import("@/features/demo/i18n/pl.json").then((m) => m.default) } },',
        "  ], gatoConfig),",
        "  en: enabledEntries<MessageLoader>([",
        '    { module: "demo", value: { key: "demo", load: () => import("@/features/demo/i18n/en.json").then((m) => m.default) } },',
        "  ], gatoConfig),",
        "};",
        "",
      ].join("\n"),
    );
  });

  it("with hasGatoConfig the client file imports the project config and wraps both lists", () => {
    expect(
      renderRegistry([full], BOTH, { hasGatoConfig: true }).client,
    ).toEqual(
      [
        "// generated by GatoJS — do not edit. Run: npm run wa -- generate",
        'import gatoConfig from "@/gato.config";',
        'import { applyGatoConfig, enabledEntries } from "@/shared/lib/modules/gato-config";',
        'import { authClientPlugin as demoAuthClientPlugin } from "@/features/demo/auth-client";',
        'import demoModule from "@/features/demo/module";',
        "",
        'export const authClientPlugins = enabledEntries([{ module: "demo", value: demoAuthClientPlugin }], gatoConfig);',
        "export const clientModules = applyGatoConfig([demoModule], gatoConfig);",
        "",
      ].join("\n"),
    );
  });

  it("without hasGatoConfig the client file aliases emptyGatoConfig", () => {
    expect(
      renderRegistry([full], BOTH, { hasGatoConfig: false }).client,
    ).toEqual(
      [
        "// generated by GatoJS — do not edit. Run: npm run wa -- generate",
        'import { emptyGatoConfig as gatoConfig } from "@/shared/lib/modules/gato-config";',
        'import { applyGatoConfig, enabledEntries } from "@/shared/lib/modules/gato-config";',
        'import { authClientPlugin as demoAuthClientPlugin } from "@/features/demo/auth-client";',
        'import demoModule from "@/features/demo/module";',
        "",
        'export const authClientPlugins = enabledEntries([{ module: "demo", value: demoAuthClientPlugin }], gatoConfig);',
        "export const clientModules = applyGatoConfig([demoModule], gatoConfig);",
        "",
      ].join("\n"),
    );
  });

  it("without options line 2 of both files is the emptyGatoConfig import", () => {
    const { server, client } = renderRegistry([full], BOTH);
    expect(server.split("\n")[1]).toBe(EMPTY_CONFIG_IMPORT);
    expect(client.split("\n")[1]).toBe(EMPTY_CONFIG_IMPORT);
    expect(server).not.toContain("@/gato.config");
    expect(client).not.toContain("@/gato.config");
  });

  it("with hasGatoConfig neither file mentions emptyGatoConfig", () => {
    const { server, client } = renderRegistry([full], BOTH, {
      hasGatoConfig: true,
    });
    expect(server).not.toContain("emptyGatoConfig");
    expect(client).not.toContain("emptyGatoConfig");
    expect(client.split("\n")[1]).toBe(CONFIG_IMPORT);
  });

  it("with no modules neither the config nor the helper import is emitted, even with hasGatoConfig", () => {
    const { server, client } = renderRegistry([], BOTH, {
      hasGatoConfig: true,
    });
    expect(server).toBe(
      [
        HEADER,
        'import type { Locale } from "@/i18n/config";',
        'import { createEnv } from "@gatojs/env";',
        "",
        "export const modules: never[] = [];",
        "export const moduleEnvSchemas: never[] = [];",
        "export const authPlugins: never[] = [];",
        "export const auditSinks: never[] = [];",
        "export const env = createEnv(moduleEnvSchemas);",
        "",
        "export type MessageLoader = { key: string; load: () => Promise<Record<string, unknown>> };",
        "",
        "export const moduleMessages: Record<Locale, MessageLoader[]> = {",
        "  pl: [],",
        "  en: [],",
        "};",
        "",
      ].join("\n"),
    );
    expect(client).toBe(
      [
        HEADER,
        "",
        "export const authClientPlugins: never[] = [];",
        "export const clientModules: never[] = [];",
        "",
      ].join("\n"),
    );
  });

  it("a module with only translations imports only enabledEntries on the server and nothing on the client", () => {
    const { server, client } = renderRegistry(
      [{ name: "gamma", ...base, locales: ["pl"] }],
      ["pl"],
      { hasGatoConfig: true },
    );
    expect(server).toBe(
      [
        HEADER,
        CONFIG_IMPORT,
        'import type { Locale } from "@/i18n/config";',
        'import { createEnv } from "@gatojs/env";',
        'import { enabledEntries } from "@/shared/lib/modules/gato-config";',
        "",
        "export const modules: never[] = [];",
        "export const moduleEnvSchemas: never[] = [];",
        "export const authPlugins: never[] = [];",
        "export const auditSinks: never[] = [];",
        "export const env = createEnv(moduleEnvSchemas);",
        "",
        "export type MessageLoader = { key: string; load: () => Promise<Record<string, unknown>> };",
        "",
        "export const moduleMessages: Record<Locale, MessageLoader[]> = {",
        "  pl: enabledEntries<MessageLoader>([",
        '    { module: "gamma", value: { key: "gamma", load: () => import("@/features/gamma/i18n/pl.json").then((m) => m.default) } },',
        "  ], gatoConfig),",
        "};",
        "",
      ].join("\n"),
    );
    expect(client).toBe(
      [
        HEADER,
        "",
        "export const authClientPlugins: never[] = [];",
        "export const clientModules: never[] = [];",
        "",
      ].join("\n"),
    );
  });

  it("a module with only module.ts imports only applyGatoConfig in both files", () => {
    const { server, client } = renderRegistry(
      [{ name: "alpha", ...base, hasModuleTs: true }],
      ["pl"],
      { hasGatoConfig: true },
    );
    expect(server.split("\n").slice(0, 7)).toEqual([
      HEADER,
      CONFIG_IMPORT,
      'import type { Locale } from "@/i18n/config";',
      'import { createEnv } from "@gatojs/env";',
      'import { applyGatoConfig } from "@/shared/lib/modules/gato-config";',
      'import alphaModule from "@/features/alpha/module";',
      "",
    ]);
    expect(server).toContain("  pl: [],\n};");
    expect(client).toBe(
      [
        HEADER,
        CONFIG_IMPORT,
        'import { applyGatoConfig } from "@/shared/lib/modules/gato-config";',
        'import alphaModule from "@/features/alpha/module";',
        "",
        "export const authClientPlugins: never[] = [];",
        "export const clientModules = applyGatoConfig([alphaModule], gatoConfig);",
        "",
      ].join("\n"),
    );
  });

  it("a module with only auth-client.ts imports only enabledEntries in the client file", () => {
    const { client } = renderRegistry(
      [{ name: "beta", ...base, hasAuthClient: true }],
      BOTH,
      { hasGatoConfig: false },
    );
    expect(client).toBe(
      [
        HEADER,
        EMPTY_CONFIG_IMPORT,
        'import { enabledEntries } from "@/shared/lib/modules/gato-config";',
        'import { authClientPlugin as betaAuthClientPlugin } from "@/features/beta/auth-client";',
        "",
        'export const authClientPlugins = enabledEntries([{ module: "beta", value: betaAuthClientPlugin }], gatoConfig);',
        "export const clientModules: never[] = [];",
        "",
      ].join("\n"),
    );
  });

  it("a module with module.ts and auth.ts only imports both helpers on the server", () => {
    expect(
      renderRegistry(
        [{ name: "alpha", ...base, hasModuleTs: true, hasAuth: true }],
        ["pl"],
        { hasGatoConfig: true },
      ).server,
    ).toBe(
      [
        HEADER,
        CONFIG_IMPORT,
        'import type { Locale } from "@/i18n/config";',
        'import { createEnv } from "@gatojs/env";',
        'import { applyGatoConfig, enabledEntries } from "@/shared/lib/modules/gato-config";',
        'import alphaModule from "@/features/alpha/module";',
        'import { authPlugin as alphaAuthPlugin } from "@/features/alpha/auth";',
        "",
        "export const modules = applyGatoConfig([alphaModule], gatoConfig);",
        "export const moduleEnvSchemas: never[] = [];",
        'export const authPlugins = enabledEntries([{ module: "alpha", value: alphaAuthPlugin }], gatoConfig);',
        "export const auditSinks: never[] = [];",
        "export const env = createEnv(moduleEnvSchemas);",
        "",
        "export type MessageLoader = { key: string; load: () => Promise<Record<string, unknown>> };",
        "",
        "export const moduleMessages: Record<Locale, MessageLoader[]> = {",
        "  pl: [],",
        "};",
        "",
      ].join("\n"),
    );
  });

  it("a module with module.ts and audit-sink.ts only imports both helpers on the server", () => {
    expect(
      renderRegistry(
        [{ name: "alpha", ...base, hasModuleTs: true, hasAuditSink: true }],
        ["pl"],
        { hasGatoConfig: true },
      ).server,
    ).toBe(
      [
        HEADER,
        CONFIG_IMPORT,
        'import type { Locale } from "@/i18n/config";',
        'import { createEnv } from "@gatojs/env";',
        'import { applyGatoConfig, enabledEntries } from "@/shared/lib/modules/gato-config";',
        'import alphaModule from "@/features/alpha/module";',
        'import { auditSink as alphaAuditSink } from "@/features/alpha/audit-sink";',
        "",
        "export const modules = applyGatoConfig([alphaModule], gatoConfig);",
        "export const moduleEnvSchemas: never[] = [];",
        "export const authPlugins: never[] = [];",
        'export const auditSinks = enabledEntries([{ module: "alpha", value: alphaAuditSink }], gatoConfig);',
        "export const env = createEnv(moduleEnvSchemas);",
        "",
        "export type MessageLoader = { key: string; load: () => Promise<Record<string, unknown>> };",
        "",
        "export const moduleMessages: Record<Locale, MessageLoader[]> = {",
        "  pl: [],",
        "};",
        "",
      ].join("\n"),
    );
  });

  it("translations in only one of two locales still import enabledEntries on the server", () => {
    expect(
      renderRegistry([{ name: "gamma", ...base, locales: ["pl"] }], BOTH, {
        hasGatoConfig: true,
      }).server,
    ).toBe(
      [
        HEADER,
        CONFIG_IMPORT,
        'import type { Locale } from "@/i18n/config";',
        'import { createEnv } from "@gatojs/env";',
        'import { enabledEntries } from "@/shared/lib/modules/gato-config";',
        "",
        "export const modules: never[] = [];",
        "export const moduleEnvSchemas: never[] = [];",
        "export const authPlugins: never[] = [];",
        "export const auditSinks: never[] = [];",
        "export const env = createEnv(moduleEnvSchemas);",
        "",
        "export type MessageLoader = { key: string; load: () => Promise<Record<string, unknown>> };",
        "",
        "export const moduleMessages: Record<Locale, MessageLoader[]> = {",
        "  pl: enabledEntries<MessageLoader>([",
        '    { module: "gamma", value: { key: "gamma", load: () => import("@/features/gamma/i18n/pl.json").then((m) => m.default) } },',
        "  ], gatoConfig),",
        "  en: [],",
        "};",
        "",
      ].join("\n"),
    );
  });

  it("a module with only env.ts imports only enabledEntries on the server", () => {
    const lines = renderRegistry(
      [{ name: "beta", ...base, hasEnv: true }],
      ["pl"],
      { hasGatoConfig: true },
    ).server.split("\n");
    expect(lines).toContain(
      'import { enabledEntries } from "@/shared/lib/modules/gato-config";',
    );
    expect(lines).not.toContain(BOTH_HELPERS_IMPORT);
    expect(lines).toContain("export const modules: never[] = [];");
  });

  it("several entries in one list are joined by a comma in input order", () => {
    const { server } = renderRegistry(
      [
        { name: "b", ...base, hasEnv: true, hasAuth: true },
        { name: "a", ...base, hasEnv: true, hasAuth: true },
      ],
      ["pl"],
      { hasGatoConfig: true },
    );
    expect(server.split("\n")).toContain(
      'export const moduleEnvSchemas = enabledEntries([{ module: "b", value: bEnvSchema }, { module: "a", value: aEnvSchema }], gatoConfig);',
    );
    expect(server.split("\n")).toContain(
      'export const authPlugins = enabledEntries([{ module: "b", value: bAuthPlugin }, { module: "a", value: aAuthPlugin }], gatoConfig);',
    );
  });

  it("several message loaders are wrapped in one enabledEntries per locale", () => {
    const { server } = renderRegistry(
      [
        { name: "alpha", ...base, locales: ["pl", "en"] },
        { name: "beta", ...base, locales: ["pl"] },
      ],
      BOTH,
      { hasGatoConfig: true },
    );
    expect(server).toContain(
      [
        "export const moduleMessages: Record<Locale, MessageLoader[]> = {",
        "  pl: enabledEntries<MessageLoader>([",
        '    { module: "alpha", value: { key: "alpha", load: () => import("@/features/alpha/i18n/pl.json").then((m) => m.default) } },',
        '    { module: "beta", value: { key: "beta", load: () => import("@/features/beta/i18n/pl.json").then((m) => m.default) } },',
        "  ], gatoConfig),",
        "  en: enabledEntries<MessageLoader>([",
        '    { module: "alpha", value: { key: "alpha", load: () => import("@/features/alpha/i18n/en.json").then((m) => m.default) } },',
        "  ], gatoConfig),",
        "};",
      ].join("\n"),
    );
  });

  it("a locale without loaders stays an empty list next to a wrapped one", () => {
    const { server } = renderRegistry(
      [{ name: "alpha", ...base, locales: ["pl"] }],
      BOTH,
      { hasGatoConfig: true },
    );
    expect(server).toContain("  ], gatoConfig),\n  en: [],\n};");
  });

  it("the module key in entries is the raw directory name, the value its identifier", () => {
    const { server, client } = renderRegistry(
      [
        {
          name: "my-feature",
          ...base,
          hasModuleTs: true,
          hasEnv: true,
          hasAuthClient: true,
        },
      ],
      ["pl"],
      { hasGatoConfig: true },
    );
    expect(server.split("\n")).toContain(
      'export const moduleEnvSchemas = enabledEntries([{ module: "my-feature", value: myFeatureEnvSchema }], gatoConfig);',
    );
    expect(server.split("\n")).toContain(
      "export const modules = applyGatoConfig([myFeatureModule], gatoConfig);",
    );
    expect(client.split("\n")).toContain(
      'export const authClientPlugins = enabledEntries([{ module: "my-feature", value: myFeatureAuthClientPlugin }], gatoConfig);',
    );
  });

  it("the helper import is emitted once per file", () => {
    const { server, client } = renderRegistry([full], BOTH, {
      hasGatoConfig: true,
    });
    expect(
      server
        .split("\n")
        .filter((line) => line.includes("@/shared/lib/modules/gato-config")),
    ).toEqual([BOTH_HELPERS_IMPORT]);
    expect(
      client
        .split("\n")
        .filter((line) => line.includes("@/shared/lib/modules/gato-config")),
    ).toEqual([BOTH_HELPERS_IMPORT]);
  });
});
